#!/usr/bin/env bash
set -euo pipefail

ROOT="${1:-$(pwd)}"
cd "$ROOT"

die() { echo "ERROR: $*" >&2; exit 1; }

git rev-parse --is-inside-work-tree >/dev/null 2>&1 || die "Run inside the Magic_Earth repo"
[[ "$(git rev-parse --abbrev-ref HEAD)" == "main" ]] || die "Must be on main"
[[ -z "$(git status --porcelain)" ]] || die "Repo is not clean; commit/stash first"

echo "==> Sync main"
git fetch origin
git pull --ff-only origin main

TMP="$(mktemp -d)"
trap 'rm -rf "$TMP"' EXIT

cat > "$TMP/r3.patch.b64" <<'B64'

B64
base64 -d "$TMP/r3.patch.b64" > "$TMP/r3.patch"

echo "==> Apply R3 fast/reliable hotfix"
if git apply --reverse --check "$TMP/r3.patch" >/dev/null 2>&1; then
  echo "R3 patch already applied."
else
  git apply --check "$TMP/r3.patch"
  git apply "$TMP/r3.patch"
fi

echo "==> Verify source markers"
grep -Fq "const RUNTIME_TUNING='r3-fast-reliable';" payload/cairodrive-google-search-only.js
grep -Fq "const SEARCH_POLL_MS=20;" payload/cairodrive-google-search-only.js
grep -Fq "const NEARBY_POLL_MS=25;" payload/cairodrive-google-search-only.js
grep -Fq "GOOGLE_RETRY endpoint=text" payload/cairodrive-google-search-only.js
grep -Fq "carEnum=known-id-0" payload/cairodrive-google-search-only.js
grep -Fq "startupFast=yes" payload/cairodrive-google-search-only.js

echo "==> Run repository verification"
./verify_patcher.sh
./VERIFY_REPO.sh
git diff --check

if git diff --quiet; then
  echo "R3 already committed; nothing to commit."
else
  git add payload/cairodrive-google-search-only.js verify_patcher.sh
  git commit -m "Fix Google search reliability and reduce runtime loading latency"
  git push origin main
fi

echo
echo "===== R3 FAST/RELIABLE HOTFIX APPLIED ====="
echo "After the new APK is built and installed, startup should log:"
echo "  hotfix=r3-fast-reliable startupFast=yes"
echo "  carEnum=known-id-0"
echo
echo "Google search should log:"
echo "  SEARCH_INTERCEPT -> GOOGLE_REQUEST -> GOOGLE_OK -> NATIVE_INJECT"
echo "or on transient failure:"
echo "  GOOGLE_NETWORK_ERROR -> GOOGLE_RETRY -> GOOGLE_REQUEST -> GOOGLE_OK -> NATIVE_INJECT"
